const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const newMexico = ee.FeatureCollection('USDOS/LSIB_sdr/2017')
    .filter(ee.Filter.eq('system:index', '26')); // New Mexico FIPS code/index in this dataset

  const geometry = newMexico.geometry();

  // Define the target date range for 2016
  const targetStartDate2016 = '2016-07-20';
  const targetEndDate2016 = '2016-07-27';

  // Define the historical period for the average
  const startYearHistorical = 2001;
  const endYearHistorical = 2010;

  // MODIS LST (MOD11A2.061: 8-day composite Land Surface Temperature)
  // LST_Day_1km band has temperature * 0.02, so convert to Celsius.
  const LST_COLLECTION = 'MODIS/061/MOD11A2';
  const LST_BAND = 'LST_Day_1km';

  // Function to mask clouds and scale LST
  const maskAndScaleLST = function(image) {
    // Select the LST band and the Quality Control band
    const lst = image.select(LST_BAND);
    const qc = image.select('QC_Day');

    // QC_Day bitmask:
    // Bits 0-1: Mandatory QA flags
    // 00 = LST produced, good quality, not used product specific QA
    // 01 = LST produced, other quality, not used product specific QA
    // 10 = LST not produced due to cloud
    // 11 = LST not produced due to other reasons
    // We want good quality (00) or other quality (01)
    const qaMask = qc.bitwiseAnd(3); // Get bits 0-1

    // Scale LST to Celsius: LST_Day_1km is in Kelvin * 0.02
    // Convert to Kelvin first, then to Celsius
    const celsius = lst.multiply(0.02).subtract(273.15);

    // Apply the quality mask
    return celsius.updateMask(qaMask.lte(1))
      .copyProperties(image, ['system:time_start', 'system:index']);
  };

  // 2. Data Acquisition & Check for 2016
  let collection2016 = ee.ImageCollection(LST_COLLECTION)
    .filterDate(targetStartDate2016, targetEndDate2016)
    .filterBounds(geometry)
    .map(maskAndScaleLST);

  const size2016 = await collection2016.size().getInfo();

  if (size2016 === 0) {
    console.log("No images found for 2016 (July 20-27).");
    console.log("C1");
    return;
  }

  // Get the single image (or average if multiple for some reason, though MOD11A2 is 8-day composite)
  // For 8-day composites, a single week often maps to one image.
  const image2016 = collection2016.mean();

  // 3. Data Acquisition & Check for Historical Average
  const julianDayStart = ee.Date(targetStartDate2016).getRelative('day', 'year');
  const julianDayEnd = ee.Date(targetEndDate2016).getRelative('day', 'year');

  let historicalCollection = ee.ImageCollection(LST_COLLECTION);

  // Filter for each year and combine
  let annualImages = [];
  for (let year = startYearHistorical; year <= endYearHistorical; year++) {
    const start = ee.Date.fromYMD(year, 1, 1).advance(julianDayStart, 'day');
    const end = ee.Date.fromYMD(year, 1, 1).advance(julianDayEnd, 'day');

    const yearCollection = historicalCollection
      .filterDate(start, end)
      .filterBounds(geometry)
      .map(maskAndScaleLST);

    const yearSize = await yearCollection.size().getInfo();
    if (yearSize > 0) {
      annualImages.push(yearCollection.mean()); // Take mean for the period if multiple images, then add to array
    }
  }

  if (annualImages.length === 0) {
    console.log("No images found for historical period (2001-2010, July 20-27).");
    console.log("C1");
    return;
  }

  const historicalAverageImage = ee.ImageCollection(annualImages).mean();

  // 4. Processing and Calculation
  // Define a reasonable scale for MODIS (1km LST_Day_1km)
  const scale = 1000; // meters

  // Reduce region for 2016
  const meanLST2016 = image2016.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });

  const countPixels2016 = image2016.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });

  const lstValue2016 = await meanLST2016.get(LST_BAND).getInfo();
  const validPixels2016 = await countPixels2016.get(LST_BAND).getInfo();

  if (validPixels2016 === 0 || lstValue2016 === null) {
    console.log("2016 LST calculation failed or no valid pixels.");
    console.log(`2016 Images: ${size2016}, Valid Pixels: ${validPixels2016}`);
    console.log(validPixels2016 === 0 ? "C2" : "C3");
    return;
  }

  // Reduce region for historical average
  const meanLSTHistorical = historicalAverageImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });

  const countPixelsHistorical = historicalAverageImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });

  const lstValueHistorical = await meanLSTHistorical.get(LST_BAND).getInfo();
  const validPixelsHistorical = await countPixelsHistorical.get(LST_BAND).getInfo();

  if (validPixelsHistorical === 0 || lstValueHistorical === null) {
    console.log("Historical LST calculation failed or no valid pixels.");
    console.log(`Historical Years with Images: ${annualImages.length}, Valid Pixels: ${validPixelsHistorical}`);
    console.log(validPixelsHistorical === 0 ? "C2" : "C3");
    return;
  }

  // 5. Validation & Final Answer
  console.log(`2016 LST (C): ${lstValue2016.toFixed(2)}, Valid Pixels: ${validPixels2016}`);
  console.log(`Historical Average LST (C): ${lstValueHistorical.toFixed(2)}, Valid Pixels: ${validPixelsHistorical}`);

  if (lstValue2016 === null || isNaN(lstValue2016) || lstValueHistorical === null || isNaN(lstValueHistorical)) {
    console.log("C3"); // Calculation resulted in null or NaN
  } else if (lstValue2016 > lstValueHistorical) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
